const FOLDERS = new Set(['concepts', 'entities', 'sources', 'syntheses', 'authored']);
const TYPE_FOLDER = { concept: 'concepts', entity: 'entities', source: 'sources', synthesis: 'syntheses', authored: 'authored', moc: '../moc' };
